import {organizePage} from './ui-layout.js';
import {MultimodalHost} from './multimodal-host.js';
import { catalogSelection, changeCatalogTarget, targetLabel, reconcileCatalogDraft } from './catalog-state.js';
import { buildTrainingRubric } from './rubrics.js';
import { examMatches,renderLibraryLink,renderExamLibrary } from './exam-library-ui.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={home:'面试练习',setup:'面试设置','exam-library':'官网考核库',devices:'设备与环境',interview:'模拟面试',reports:'面试结果',sources:'参考资料'};
const kindNames={resume:'个人简历',portfolio:'作品集',rules:'面试考核细则',rubric:'评分标准'};
const sensorNames={camera:'摄像头',audio:'麦克风',hand:'手部动作',imu:'躯干IMU',gaze:'眼动仪'};
function saved(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}
let config,materials=[],sessions=[],sources=[],current=null,searchResults=[],page='home',examLibrary={records:[]};
let libraryFilter={schoolId:'',collegeId:'',year:'',admissionType:''};
let selected=saved('onstage.materials',{});
let draft=saved('onstage.draft',null)||{nickname:'',school:'',major:'设计学',year:'2027',admissionType:'推免面试',interviewTime:new Date(Date.now()+86400000).toLocaleString('sv-SE').slice(0,16).replace(' ','T'),attempt:1,rulesText:'',rubricText:'',stages:['english','portfolio','design','ethics'],official:[]};
let answerStarted=0;
let camera=null,mic=null,recognition=null,speechStarted=0,speechConsent=false,toastTimer,busy=false,answerDraft='',recording=false;
async function api(url,options={}) {
  const res=await fetch(url,{...options,headers:options.body instanceof FormData?{}:{'Content-Type':'application/json',...options.headers}});
  const data=await res.json();if(!res.ok)throw new Error(data.error||'操作未完成');return data;
}
const post=(url,data)=>api(url,{method:'POST',body:JSON.stringify(data)});
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
const multimodal=new MultimodalHost({api,post,toast});
function persist(){localStorage.setItem('onstage.draft',JSON.stringify(draft));localStorage.setItem('onstage.materials',JSON.stringify(selected));}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtle">${subtitle}</p></div>${action}</div>`;}
function badge(text,kind=''){return `<span class="pill ${kind}">${esc(text)}</span>`;}
function number(value,suffix=''){return value==null?'待评估':`${esc(value)}${suffix}`;}
function officialProvenance(profile){const r=profile.examLibrary;return r?`<p class="page-note">本场依据：<a href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><br>${esc(r.year)} 年 / ${esc(r.admissionType)} / ${esc(r.checkedAt)} 核验${r.userEdited?' / 含本人编辑确认内容':' / 已保存官网摘要快照'}。${r.userEdited?'含本人编辑的内容，具体权重以本场确认表为准；官网原始结构见来源。':r.officialRubric?.length?'权重据官网，观察要求经产品转译。':'官网未公布内部权重。'}</p>`:'<p class="page-note">依据本场上传或手动填写并确认的院校材料。</p>';}
const evidenceStatusNames={observed:'已观察',partly_observed:'部分观察',not_assessed:'未考察',skipped:'已跳过',insufficient_evidence:'证据不足'};
const hasScore=value=>typeof value==='number'&&Number.isFinite(value);
const textValue=value=>typeof value==='string'?value:Array.isArray(value)?value.map(textValue).filter(Boolean).join('；'):value&&typeof value==='object'?String(value.text??value.question??value.suggestion??value.name??value.reason??''):'';
const countValue=value=>Array.isArray(value)?value.length:hasScore(value)?value:0;
function evidenceState(item){return item.status??(hasScore(item.score)?'observed':'not_assessed');}
function evidenceBadge(item){const state=evidenceState(item);return `<span class="evidence-status ${esc(state)}">${evidenceStatusNames[state]??'待复盘'}</span>`;}
function targetRubric(target){return buildTrainingRubric(target);}
function rubricPanel(target, supplied=null, compact=false){
  const rubric=supplied??targetRubric(target),dimensions=rubric.dimensions??[],languages=rubric.languageDimensions??[];
  return `<section class="card rubric-section ${compact?'rubric-compact':''}" id="target-rubric-preview" data-rubric-id="${esc(rubric.id)}"><div class="rubric-heading"><div><p class="eyebrow">CRITERIA BEFORE PRACTICE</p><h2>${compact?'本场评分依据':'按目标专业生成的训练评分表'}</h2><p class="subtle">${esc(rubric.targetLabel||targetLabel(target)||'请选择目标专业，训练重点会随之调整')}</p></div><span class="rubric-label">${supplied?'本场已冻结':'训练建议量表'}</span></div><div class="rubric-intro"><div><h3>${esc(rubric.name)}</h3><p>${esc(rubric.rationale)}</p></div><div class="rubric-contract"><span>先确定标准</span><span>引用实际回答</span><span>覆盖与质量分开</span></div></div>${compact?`<div class="rubric-summary">${dimensions.map(d=>`<span>${esc(d.name)} <b>${d.weight}%</b></span>`).join('')}</div>`:`<div class="rubric-dimensions">${dimensions.map((d,i)=>`<article class="rubric-dimension"><div class="rubric-dimension-heading"><span class="dimension-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(d.name)} ${d.critical?'<span class="critical-dot" title="完整结论所需的关键维度">●</span>':''}</h3><span class="dimension-weight">${d.weight}%</span></div><p class="criterion">${esc(d.criterion)}</p><div class="expected-evidence"><span>需要的证据</span><p>${esc(textValue(d.evidenceExpected))}</p></div><div class="anchor-grid">${(d.anchors??[]).map((anchor,n)=>`<div><b>${[1,3,5][n]} 分</b><p>${esc(textValue(anchor))}</p></div>`).join('')}</div></article>`).join('')}</div><div class="rubric-language"><div><span class="eyebrow">COMMUNICATION, SEPARATELY</span><h3>表达反馈，单独反馈</h3><p>文字转写可观察表达清晰度、结构和术语使用。英语环节不凭转写推断发音或口音。</p></div><div class="language-criteria">${languages.map(d=>`<div><strong>${esc(d.name)}</strong><p>${esc(d.criterion)}</p></div>`).join('')}</div></div>`}<p class="rubric-footnote">${supplied?'采用本场开始前确定的量表快照，后续目录或量表变化不会改写本场标准。':'权重是本产品的训练建议，随目标专业与方向调整，不是院校官方规定。'} 未考察、跳过和证据不足分别记录，不记为 0 分。${rubric.source?.url?` <a href="${esc(safeURL(rubric.source.url))}" target="_blank" rel="noopener noreferrer">证据评价规则来源 ↗</a>`:''}</p></section>`;
}
function formField(label,name,value,type='text'){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="1" max="9999"':''} required></label>`;}
function targetFields(){
  const s=catalogSelection(config.templates,draft),custom=!s.school;
  const select=(label,name,value,items,placeholder,disabled=false)=>`<label class="field">${label}<select name="${name}" ${disabled?'disabled':''} required><option value="">${placeholder}</option>${items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.label??x.name)}</option>`).join('')}</select></label>`;
  const school=`<label class="field">学校<select name="schoolId" required><option value="">请选择学校</option>${config.templates.filter(t=>t.id!=='custom').map(t=>`<option value="${t.id}" ${s.school?.id===t.id?'selected':''}>${t.school}</option>`).join('')}<option value="custom" ${(draft.schoolId==='custom'||custom&&draft.school)?'selected':''}>其他院校（自定义）</option></select></label>`;
  let fields=school;
  if(custom&&(draft.schoolId==='custom'||draft.school)){fields+=`${formField('学校名称','school',draft.school)}${formField('学院名称','college',draft.college||'')}${formField('专业名称','major',draft.major)}`;}
  else if(custom){fields+=select('学院','collegeId','',[],'请先选择学校',true)+select('报考专业','programId','',[],'请先选择学院',true);}
  else{
    fields+=select('学院','collegeId',draft.collegeId,s.colleges,'请选择学院');
    fields+=select('报考专业','programId',draft.programId,s.programs.map(p=>({...p,label:`${p.code} ${p.name} / ${p.degree}`})),s.college?'请选择专业':'请先选择学院',!s.college);
    fields+=`<input type="hidden" name="school" value="${esc(s.school.school)}"><input type="hidden" name="college" value="${esc(s.college?.name||'')}"><input type="hidden" name="major" value="${esc(s.program?.name||'')}">`;
    if(s.directions.length)fields+=`<label class="field">研究方向${s.program.requireDirection?'':'（可选）'}<select name="directionId" ${s.program.requireDirection?'required':''}><option value="">${s.program.requireDirection?'请选择设计相关方向':'暂不细分方向'}</option>${s.directions.map(d=>`<option value="${d.id}" ${s.direction?.id===d.id?'selected':''}>${esc((d.code?`${d.code} ${d.name}`:d.name)+(d.studyMode?' / '+d.studyMode:''))}</option>`).join('')}</select></label>`;
  }
  return fields;
}
function catalogNote(){
  const s=catalogSelection(config.templates,draft),p=s.program;
  if(!s.school)return '<p class="page-note"></p>';
  if(!p)return `<p class="page-note">${draft.major?'旧设置“'+esc(draft.major)+'”需按目录重新选择。':''}</p>`;
  const c=p.catalog;
  return `<div class="help"><strong>${esc(targetLabel({...draft,college:s.college.name,major:p.name,majorCode:p.code}))}</strong><br>${esc(c.label)} / 核对日期 ${esc(c.checkedAt)}${Number(c.year)!==Number(draft.year)?`<br>当前目标为 ${esc(draft.year)} 年，参考资料年份为 ${c.year}，需另核对目标年度细则。`:''}${c.admissionTypes.length&&!c.admissionTypes.includes(draft.admissionType)?'<br>当前招生类型不在这份目录的已核对范围内，请确认适用性。':''}<br><a href="${esc(safeURL(c.url))}" target="_blank" rel="noopener noreferrer">查看官网来源 ↗</a>${(p.sources??[]).filter(x=>x.url!==c.url).map(x=>` / <a href="${esc(safeURL(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.label)} ↗</a>`).join('')}${p.scopeNote?'<br>'+esc(p.scopeNote):''}</div><p class="page-note">专业与方向目录不代替院校的面试细则和评分标准，仍需为本次目标上传确认。</p>`;
}
function sessionRows(list){return list.length?`<div class="scroll-table"><table class="session-table"><thead><tr><th>院校 / 专业</th><th>面试时间</th><th>次数</th><th>状态</th><th>操作</th></tr></thead><tbody>${list.map(s=>`<tr><td>${esc(s.profile.school)}<br><span class="subtle">${esc([s.profile.college,s.profile.majorCode,s.profile.major,s.profile.direction].filter(Boolean).join(' / '))} / ${esc(s.profile.nickname)}</span></td><td>${esc(s.profile.interviewTime.replace('T',' '))}</td><td>第 ${s.profile.attempt} 次</td><td>${badge(s.status==='complete'?'已完成':s.status==='paused'?'已暂停':'进行中',s.status==='complete'?'green':'')}</td><td><button class="small secondary" data-session="${s.id}">${s.status==='complete'?'查看复盘':'继续面试'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">暂无练习记录</div>';}
function home(){
  const recent=sessions.find(s=>s.status==='complete');
  const finished=sessions.filter(s=>s.status==='complete');
  return `<section class="home-stage" aria-labelledby="home-title"><div class="home-art" aria-hidden="true"><span class="home-art-piece home-art-left"></span><span class="home-art-piece home-art-right"></span><span class="home-art-orbit home-art-orbit-one"></span><span class="home-art-orbit home-art-orbit-two"></span></div><div class="home-stage-content"><h1 id="home-title" aria-label="下一场面试，准备更充分。"><span class="home-title-text">下一场面试，准备更充分。</span><span class="home-slogan-art" aria-hidden="true"></span></h1><p class="home-stage-subtitle">围绕作品与研究经历，练习有依据的表达。</p></div></section>
  <section class="home-overview" aria-label="练习概览"><h2>练习概览</h2><div class="home-stat"><strong>${finished.length}</strong><span>已完成练习</span></div><div class="home-stat"><strong>${finished.reduce((n,x)=>n+(x.report?.coverage?.answered||0),0)}</strong><span>已回答题目</span></div>${recent?`<div class="home-last-target"><span>最近目标</span><strong>${esc([recent.profile.school,recent.profile.major].join(' / '))}</strong></div>`:''}</section>
  <div class="section-row"><h2>练习记录</h2><a class="subtle" href="#reports">查看全部</a></div><section class="card">${sessionRows(sessions.slice(0,5))}</section><details class="stage-overview"><summary>可练习的面试环节</summary><div class="practice-grid">${config.stages.map((x,i)=>`<section class="practice-card"><span class="practice-icon">${['Aa','▧','✧','◇'][i]}</span><h3>${x.name}</h3><p>${['研究兴趣与英文问答','项目贡献与设计决策','专业知识与研究方法','学习规划与设计伦理'][i]}</p></section>`).join('')}</div></details>`;
}
function setup(){return heading('面试设置','')+`<form id="setup-form">
  <section class="card"><h2><span class="step">01</span> 面试目标</h2><div class="form-grid">${targetFields()}${formField('昵称','nickname',draft.nickname)}${formField('招生年份','year',draft.year,'number')}<label class="field">招生类型<select name="admissionType">${['推免面试','研究生复试','海外院校面试','其他升学面试'].map(x=>`<option ${x===draft.admissionType?'selected':''}>${x}</option>`).join('')}</select></label>${formField('面试时间','interviewTime',draft.interviewTime,'datetime-local')}${formField('练习次数','attempt',draft.attempt,'number')}</div>${catalogNote()}</section>
  ${rubricPanel(draft)}
  <section class="card form-section"><h2><span class="step">02</span> 准备材料</h2><div class="upload-grid">${Object.entries(kindNames).filter(([kind])=>['resume','portfolio'].includes(kind)).map(([kind,label])=>{const m=materials.find(m=>m.id===selected[kind]);return `<div class="upload"><div class="practice-icon">${kind==='portfolio'?'▧':'↥'}</div><h3>${label}</h3><label>选择文件<input type="file" data-upload="${kind}" accept=".pdf,.txt,.md,.json,.png,.jpg,.jpeg,.webp"></label><span class="filename">${m?esc(m.name):'尚未上传'}</span>${m?badge(['parsed','user_described'].includes(m.status)?'已读取':'需补充文字',m.status==='parsed'?'green':'gray'):''}</div>`;}).join('')}</div><p class="page-note">支持PDF、文本和图片，单份不超过20MB。扫描件请补充文字。</p><label class="field form-section">作品补充说明（选填）<textarea name="portfolioNotes" placeholder="项目名称、对应页码、设计问题、你的贡献、研究和验证过程">${esc(draft.portfolioNotes||'')}</textarea></label></section>
  <section class="card form-section"><h2><span class="step">03</span> 考核规则</h2>${renderLibraryLink(examLibrary,draft)}<details class="rule-imports"><summary>从文件导入规则</summary><div class="grid two"><label class="field">考核要求文件<input type="file" data-upload="rules" accept=".pdf,.txt,.md,.json,.png,.jpg,.jpeg,.webp"></label><label class="field">评分标准文件<input type="file" data-upload="rubric" accept=".pdf,.txt,.md,.json,.png,.jpg,.jpeg,.webp"></label></div></details><div class="grid two"><label class="field">面试考核要求<textarea name="rulesText" required placeholder="上传细则后自动填入可提取文字；也可粘贴官方原文，注明年份、招生类型和环节。">${esc(draft.rulesText)}</textarea></label><label class="field">院校评分标准<textarea name="rubricText" required placeholder="上传评分标准后自动填入，未知权重不要自行推定。">${esc(draft.rubricText)}</textarea></label></div><details class="optional-settings"><summary>院校评分项与权重（选填）</summary><p class="page-note">仅填写官网已公布的权重。</p><div id="official-rows">${officialRows()}</div><button type="button" class="small secondary" data-action="add-rubric">＋ 添加院校评分项</button></details></section>
  <section class="card form-section"><h2><span class="step">04</span> 练习环节</h2>${config.stages.map(s=>`<div class="stage-row"><input type="checkbox" name="stages" value="${s.id}" id="stage-${s.id}" ${draft.stages.includes(s.id)?'checked':''}><label for="stage-${s.id}">${s.name}</label><input type="number" name="minutes-${s.id}" min="1" max="30" value="${draft['minutes-'+s.id]??s.minutes}" aria-label="${s.name}时长"><span class="subtle">分钟</span></div>`).join('')}</section>
  <div class="form-actions"><a class="button secondary" href="#devices">设备与环境</a><button type="submit">开始面试</button></div></form>`;}
function officialRows(){return(draft.official||[]).map((x,i)=>`<div class="official-row" data-rubric-row="${i}"><input name="rubric-name-${i}" value="${esc(x.name)}" placeholder="评分项名称" aria-label="评分项名称"><input name="rubric-weight-${i}" type="number" min="0.01" max="100" step="0.01" value="${esc(x.weight)}" placeholder="权重 %" aria-label="权重百分比"><input name="rubric-criterion-${i}" value="${esc(x.criterion)}" placeholder="对应细则原文或具体评价要求" aria-label="评分依据"><button type="button" class="small ghost" data-remove-rubric="${i}" aria-label="移除评分项">×</button></div>`).join('');}
function captureDraft(){const form=$('#setup-form');if(!form)return;const f=new FormData(form);for(const name of ['nickname','school','college','major','year','admissionType','interviewTime','attempt','rulesText','rubricText','portfolioNotes'])draft[name]=f.get(name); for(const name of ['schoolId','collegeId','programId','directionId'])draft[name]=f.get(name)||''; const selection=catalogSelection(config.templates,draft); draft.direction=selection.direction?.name||''; draft.majorCode=selection.program?.code||'';draft.stages=f.getAll('stages');for(const s of config.stages)draft['minutes-'+s.id]=Number(f.get('minutes-'+s.id));draft.official=[...form.querySelectorAll('[data-rubric-row]')].map((row,i)=>({id:`criterion_${i+1}`,name:f.get(`rubric-name-${i}`),weight:Number(f.get(`rubric-weight-${i}`)),criterion:f.get(`rubric-criterion-${i}`)}));persist();}
function devices(){return heading('设备与环境','','<a href="#setup" class="button secondary small">返回面试设置</a>')+`
  <section class="device-statuses" aria-label="设备连接状态">
    <div class="device-state"><h2>摄像头与手部</h2><p id="device-camera-state">${multimodal.state.camera?'已连接':'未连接'}</p></div>
    <div class="device-state"><h2>身体姿态 IMU</h2><p id="device-imu-state">${multimodal.state.imu?(multimodal.state.calibrated?'已校准':'待校准'):'未连接'}</p></div>
    <div class="device-state"><h2>麦克风</h2><p>${mic?'已连接':'未检查'}</p></div>
  </section>
  <div class="device-audio"><label class="checkline"><input id="speech-consent" type="checkbox" ${speechConsent?'checked':''}><span>启用浏览器语音转写（音频可能由浏览器服务商处理）</span></label><button data-action="mic-test" class="small secondary">${mic?'结束设备检查':'检查麦克风'}</button></div>`;}
function interview(){
  if(!current||current.status==='complete')return heading('模拟面试','')+`<section class="card empty"><h2>准备好，开始你的下一场</h2><p>先选择院校专业、上传材料与考核依据，再生成本场计划。</p><a class="button" href="#setup">新建面试</a></section>`;
  const stage=current.profile.stages[current.stageIndex],last=current.turns.at(-1),answered=last.role==='candidate',paused=current.status==='paused';
  return heading('模拟面试',`${esc(current.profile.school)} / ${esc([current.profile.college,current.profile.major,current.profile.direction].filter(Boolean).join(' / '))} / 第 ${current.profile.attempt} 次`,`${badge(current.mode==='demo'?'流程演示 / 暂不评分':'模型已连接')} <span class="timer" id="elapsed">00:00</span>`)+
  `<div class="stage-tabs">${current.profile.stages.map((s,i)=>`<span class="stage-tab ${i===current.stageIndex?'current':i<current.stageIndex?'done':''}">${i+1}. ${s.name}</span>`).join('')}</div>${(current.warnings??[]).map(w=>`<div class="help">${esc(w)}</div>`).join('')}<div class="interview-layout"><div><section class="examiner"><img src="/assets/examiner.webp" alt="虚构的设计学院教师型练习考官"><span class="examiner-badge">${stage.name} / 虚拟考官</span><div class="examiner-caption">${paused?'面试已暂停':esc([...current.turns].reverse().find(t=>t.role==='interviewer')?.content)}</div></section><div class="interview-controls"><button class="ghost" data-action="camera">${multimodal.state.camera?'关闭画面':'开启画面'}</button><button class="ghost" data-action="speak">朗读问题</button><button class="secondary" data-control="${paused?'resume':'pause'}">${paused?'恢复面试':'暂停'}</button><button class="danger" data-control="finish">结束面试</button></div><section class="card"><h2>本场依据</h2><p class="subtle">${esc((current.rubric??current.profile.trainingRubric)?.name||'沿用本场已确定的标准')} / 内容评价与语言反馈分开</p><p class="subtle">${stage.name} / 建议 ${stage.minutes} 分钟 / ${current.profile.year} ${esc(current.profile.admissionType)}</p><div class="actions">${current.materials.filter(m=>['resume','portfolio'].includes(m.kind)).map(m=>`<a class="button secondary small" href="/api/materials/${m.id}/file" target="_blank" rel="noopener">查看${kindNames[m.kind]} ↗</a>`).join('')}</div><details><summary>查看七层面试计划</summary><p class="page-note">${Object.keys(current.plan.layers).map((k,i)=>`${i+1}. ${['院校专业与考核','学生与作品画像','环节考官','提问追问策略','材料与证据缺口','评分框架','面试节奏'][i]}`).join(' / ')}</p><p class="subtle">${esc(current.plan.layers.gaps.join('；')||'按已上传材料进行练习。')}</p></details></section></div><section class="card"><h2>问答记录</h2><div class="transcript">${current.turns.map(t=>`<div class="turn ${t.role}"><div class="who">${t.role==='candidate'?'你':'考官'} / ${config.stages.find(s=>s.id===t.stageId)?.name||''}</div><div class="bubble">${esc(t.skipped?'本题已跳过，不作为错误答案计分。':t.content)}</div></div>`).join('')}</div>${answered?`<div class="feedback recording-note"><strong>${last.skipped?'本题已跳过':'回答已记录'}</strong><p>结束后查看反馈。</p></div><div class="actions"><button data-control="followup" ${paused?'disabled':''}>继续追问</button>${current.stageIndex<current.profile.stages.length-1?`<button class="secondary" data-control="next" ${paused?'disabled':''}>下一环节 →</button>`:'<button class="secondary" data-control="finish">结束并查看复盘</button>'}</div>`:`<form id="answer-form"><label class="field">你的回答<textarea class="answer-box" name="answer" maxlength="20000" required ${paused?'disabled':''} placeholder="输入回答，或使用语音转写">${esc(answerDraft)}</textarea></label><p class="subtle ${recording?'recording':''}" id="speech-status">${recording?'● 正在转写，结束后请检查文字':''}</p><div class="actions"><button type="button" data-action="speech" class="secondary" ${paused?'disabled':''}>${recording?'停止转写':'语音输入'}</button><button type="submit" ${paused?'disabled':''}>提交回答</button><button type="button" class="ghost" data-control="skip" ${paused?'disabled':''}>暂时跳过</button></div><label class="checkline form-section"><input id="speech-consent" type="checkbox" ${speechConsent?'checked':''}><span>启用语音转写（音频可能由浏览器服务商处理）</span></label></form>`}</section></div>`;
}
function legacyReports(){
  const s=current?.report?current:null;
  if(!s)return heading('面试结果','')+`<section class="card">${sessionRows(sessions.filter(s=>s.status==='complete'))}</section>`;
  const r=s.report;
  return heading('面试结果',`${esc(s.profile.school)} / ${esc([s.profile.college,s.profile.majorCode,s.profile.major,s.profile.direction].filter(Boolean).join(' / '))} / ${esc(s.profile.nickname)} / 第 ${s.profile.attempt} 次`,`<div class="actions"><a class="button secondary small" href="/api/sessions/${s.id}/export?format=md" title="Markdown 文本报告">导出报告</a><a class="button secondary small" href="/api/sessions/${s.id}/export" title="JSON 原始数据">导出数据</a></div>`)+
  `<div class="stats"><section class="card"><span class="subtle">六维训练反馈 / 100</span><strong>${number(r.trainingTotal)}</strong><span class="subtle">${r.coverage.assessed} / ${r.coverage.total} 个维度有评分证据</span></section><section class="card"><span class="subtle">按院校标准的练习分 / 100</span><strong>${number(r.official.total)}</strong><span class="subtle">${esc(r.official.note||'暂无院校评分')}</span></section><section class="card"><span class="subtle">本场完成</span><strong>${r.coverage.answered} <small>题</small></strong><span class="subtle">覆盖 ${r.coverage.stageIds.length} / ${s.profile.stages.length} 个环节 / ${s.mode==='demo'?'流程演示':'模型评价'}</span></section></div><div class="grid two"><section class="card"><h2>训练维度</h2>${r.dimensions.map(d=>`<div class="bar-item"><div class="bar-label"><span>${d.name}</span><span>${number(d.score,' / 5')}</span></div>${hasScore(d.score)?`<div class="bar"><div class="bar-fill" data-width="${d.score*20}"></div></div>`:'<div class="no-score-track">尚无评分证据</div>'}</div>`).join('')}<p class="page-note">${esc(r.note)}</p></section><section class="card"><h2>与上次可比练习对照</h2>${r.comparison?`<p class="subtle">对比第 ${r.comparison.attempt} 次，院校专业、招生类型、评分版本与环节一致。</p>${r.comparison.items.map(x=>`<div class="bar-label"><span>${x.name}</span><span>${x.change===null?'证据不足':`${x.change>0?'+':''}${x.change}`}</span></div>`).join('')}`:'<div class="empty">暂时没有同一评分标准下的可比记录。</div>'}<h3>下次重点</h3>${r.improvements.length?r.improvements.map((x,i)=>`<label class="checkline"><input type="checkbox" data-improvement="${i}" ${x.checked ? "checked" : ""}><span>${esc(x.dimension)}：${esc(x.suggestion)}</span></label>`).join(''):'<p class="subtle">取得内容评分后，会生成基于回答证据的改进清单。</p>'}</section></div><section class="card form-section"><h2>采集状态</h2><div class="sensor-grid">${r.sensorSummary.map(x=>`<div class="sensor-cell"><strong>${sensorNames[x.channel]}</strong><span class="subtle">${x.count?`${x.count} 条状态事件`:'未采集'}</span></div>`).join('')}</div><p class="page-note">设备状态不参与专业得分。手部与姿态复盘见下方采集报告，动作观察不参与专业得分。</p></section><section class="card"><h2>问答回看</h2>${s.turns.filter(t=>t.role==='candidate').map((t,i)=>`<article class="evidence"><h3>${i+1}. ${esc(s.turns.find(q=>q.id===t.questionId)?.content)}</h3><blockquote>${esc(t.content)}</blockquote><p>${esc(t.evaluation.feedback)}</p>${t.evaluation.dimensions.filter(d=>d.score!==null).map(d=>`<details><summary>${esc(d.name)} / ${d.score} / 5</summary><blockquote>${esc(d.quote)}</blockquote><p>${esc(d.reason)}</p><p>改进：${esc(d.improvement)}</p></details>`).join('')}</article>`).join('')||'<p class="subtle">本场尚未作答</p>'}</section>${r.official.items?.length?`<section class="card"><h2>院校评分依据</h2>${r.official.items.map(d=>`<article class="evidence"><h3>${esc(d.name)} / ${d.weight}% / ${number(d.score)}</h3><blockquote>${esc(d.quote)}</blockquote><p>${esc(d.reason)}</p></article>`).join('')}</section>`:''}<div class="form-actions"><button class="secondary" data-action="new-attempt">按此院校再练一次 →</button></div>`;
}
function evidenceDimensionCards(dimensions){
  return '<div class="score-dimensions">'+(dimensions??[]).map(d=>'<article class="score-dimension '+esc(evidenceState(d))+'"><div class="score-dimension-top"><h3>'+esc(d.name)+'</h3>'+evidenceBadge(d)+'</div><div class="score-value">'+(hasScore(d.score)?esc(d.score)+' <small>/ 5</small>':'<span class="score-empty">'+(evidenceStatusNames[evidenceState(d)]??'待评估')+'</span>')+'</div>'+(hasScore(d.score)?'<div class="bar"><div class="bar-fill" data-width="'+(d.score*20)+'"></div></div>':'<div class="no-score-track"></div>')+'<p class="subtle">'+(d.independentEvidenceCount??d.observedAnswers??(d.evidence??[]).filter(e=>e.quote).length)+' 条独立回答证据'+(d.duplicateEvidenceCount?' / '+d.duplicateEvidenceCount+' 条重复片段已合并':'')+'</p></article>').join('')+'</div>';
}
function evidenceCard(e,s,index){
  const answer=s.turns.find(t=>t.id===e.responseId),question=s.turns.find(t=>t.id===(e.questionId??answer?.questionId));
  const quote=textValue(e.quote),nextProbe=textValue(e.nextProbe);
  return '<article class="evidence-record '+(e.group==='language'?'language-record':'')+'" data-evidence-record="'+esc(e.id??index)+'"><div class="evidence-record-head"><div><span class="evidence-id">E'+String(index+1).padStart(2,'0')+'</span><strong>'+esc(e.name??e.dimension??e.dimensionId??'回答证据')+'</strong></div>'+evidenceBadge(e)+'</div>'+(question?.content||e.question?'<p class="evidence-question">问题：'+esc(question?.content??e.question)+'</p>':'')+(quote?'<blockquote>'+esc(quote)+'</blockquote>':'<p class="unobserved-note">没有足够的回答证据支持本项判断。</p>')+'<dl class="evidence-notes">'+(e.reason||e.quality?'<div><dt>判断依据</dt><dd>'+esc(textValue(e.reason??e.quality))+'</dd></div>':'')+(e.limitation?'<div><dt>事实边界</dt><dd>'+esc(textValue(e.limitation))+'</dd></div>':'')+(nextProbe?'<div><dt>下一追问</dt><dd>'+esc(nextProbe)+'</dd></div>':'')+'</dl>'+(Array.isArray(e.counterevidence)&&e.counterevidence.length?'<details><summary>反例与修正 / '+e.counterevidence.length+' 条</summary>'+e.counterevidence.map(x=>'<blockquote>'+esc(x.quote??textValue(x))+'</blockquote><p class="subtle">'+esc(x.reason??x.limitation??'')+'</p>'+(x.correction?'<p class="evidence-correction">修正判断：'+esc(x.correction)+'</p>':'')).join('')+'</details>':'')+'<div class="evidence-record-foot"><span class="subtle">'+(e.independent===false||e.duplicateOf?'重复片段，不增加独立证据':e.group==='language'?'语言表达证据':'专业能力证据')+'</span>'+(answer?'<button type="button" class="small ghost" data-jump-answer="'+esc(answer.id)+'">定位原回答 ↗</button>':'')+'</div></article>';
}
function reportQuestions(s){
  return '<section class="card report-questions" id="answer-records"><div class="report-section-heading"><div><p class="eyebrow">ANSWER BY ANSWER</p><h2>问答回看</h2></div><span class="subtle"></span></div>'+s.turns.filter(t=>t.role==='candidate').map((t,i)=>{
    const ev=t.evaluation??{},q=s.turns.find(q=>q.id===t.questionId),all=[...(ev.dimensions??[]),...(ev.languageDimensions??[])];
    return '<article class="answer-record" id="answer-'+esc(t.id)+'"><div class="answer-record-heading"><span class="question-index">'+String(i+1).padStart(2,'0')+'</span><div><span class="subtle">'+esc(config.stages.find(st=>st.id===t.stageId)?.name??'面试回答')+'</span><h3>'+esc(q?.content??'本题回答')+'</h3></div>'+(t.skipped?badge('已跳过','gray'):'')+'</div>'+(t.skipped?'<div class="unobserved-note">本题已跳过</div>':'<blockquote class="original-answer">'+esc(t.content)+'</blockquote>')+(ev.feedback?'<p class="question-feedback">'+esc(ev.feedback)+'</p>':'')+'<div class="question-statuses">'+all.map(d=>'<span>'+esc(d.name??d.id)+' '+evidenceBadge(d)+'</span>').join('')+'</div>'+(ev.improvedAnswer||ev.exercise?'<details class="coaching-details"><summary>改写建议与下一步练习</summary>'+(ev.improvedAnswer?'<div class="coaching-block"><h4>改写建议</h4><p>'+esc(textValue(ev.improvedAnswer))+'</p><span class="subtle">仅示范表达组织，不能作为个人经历的新增证据。</span></div>':'')+(ev.exercise?'<div class="coaching-block"><h4>下一步练习</h4><p>'+esc(textValue(ev.exercise))+'</p></div>':'')+'</details>':'')+'</article>';
  }).join('')+(s.turns.some(t=>t.role==='candidate')?'':'<div class="empty">本场尚未作答</div>')+'</section>';
}
function reports(){
  const s=current?.report?current:null;
  if(!s)return heading('面试结果','')+'<section class="card">'+sessionRows(sessions.filter(s=>s.status==='complete'))+'</section>';
  const r=s.report,rubric=r.rubric??s.rubric??s.profile.trainingRubric;
  if(!rubric)return '<div class="help legacy-notice">这是一份旧版评分记录，保留当时的量表与结果，不用新版专业标准重新打分。</div>'+legacyReports();
  const coverage=r.coverage??{},dimensions=r.dimensions??[],languages=r.languageDimensions??[],official=r.official??{items:[],total:null},critical=(coverage.criticalMissing??[]).map(x=>typeof x==='string'?(dimensions.find(d=>d.id===x)?.name??x):x.name??x.dimension??x.id).filter(Boolean);
  const ledger=Array.isArray(r.evidenceLedger)?r.evidenceLedger:dimensions.flatMap(d=>(d.evidence??[]).map(e=>({...e,name:d.name,dimensionId:d.id,group:'professional'})));
  const quoted=ledger.filter(e=>e.quote),pending=ledger.filter(e=>!e.quote),assessment=r.assessmentStatus??(hasScore(r.trainingTotal)?'complete':'partial');
  const statusLabel={complete:'已有完整训练结论',partial:'当前为部分结论',unassessed:'本场尚未形成完整评价',assisted_practice:'辅助练习记录',legacy:'旧版记录'}[assessment]??'当前为部分结论';
  return heading('面试结果',esc(targetLabel(s.profile))+' / '+esc(s.profile.nickname)+' / 第 '+s.profile.attempt+' 次','<div class="actions"><a class="button secondary small" href="/api/sessions/'+s.id+'/export?format=md" title="Markdown 文本报告">导出报告</a><a class="button secondary small" href="/api/sessions/'+s.id+'/export" title="JSON 原始数据">导出数据</a></div>')+
  (s.contentRegrade?'<p class="page-note">补评来源：'+esc(s.contentRegrade.sourceLabel||s.contentRegrade.method)+'。'+esc(s.contentRegrade.limitations||'')+'</p>':'')+
  '<section class="assessment-summary"><div><p class="eyebrow">EVIDENCE BEFORE CONCLUSION</p><h2>'+statusLabel+'</h2><p>'+esc(critical.length?'待补充：'+critical.join('、')+'。':hasScore(r.trainingTotal)?'依据本场实际回答形成训练反馈。分数只适用于当前考察范围。':'没有足够证据时保留待评估，未考察不等于能力较弱。')+'</p></div><div class="assessment-score"><span>专业训练参考 / 100</span><strong>'+(hasScore(r.trainingTotal)?esc(r.trainingTotal):'暂不汇总')+'</strong><small>'+esc(rubric.name)+'</small></div></section>'+
  '<section class="card coverage-panel" id="coverage-panel"><div class="report-section-heading"><div><p class="eyebrow">WHAT WAS OBSERVED</p><h2>考察覆盖</h2></div>'+badge(s.contentRegrade?.method==='assistant_rubric_review'?'量表补评':s.mode==='demo'?'流程演示 / 暂不评分':s.mode==='llm'?'模型评价':'本场记录')+'</div><div class="coverage-metrics"><div><strong>'+countValue(coverage.assessed)+'<small> / '+(coverage.total??dimensions.length)+'</small></strong><span>已评价维度</span></div><div><strong>'+countValue(coverage.partial)+'</strong><span>部分观察</span></div><div><strong>'+countValue(coverage.unassessed)+'</strong><span>待补证据</span></div><div><strong>'+countValue(coverage.answered)+'</strong><span>已回答题目</span></div></div><p class="page-note">本场覆盖 '+(coverage.stageIds??[]).map(id=>esc(config.stages.find(st=>st.id===id)?.name??id)).join('、')+'。重复回答不会增加独立证据；错误是回答质量判断，不会与“未考察”混淆。</p></section>'+
  '<section class="card"><div class="report-section-heading"><div><p class="eyebrow">PROFESSIONAL QUALITY</p><h2>专业能力反馈</h2></div><span class="subtle">'+esc(rubric.version)+' / 本场评价标准</span></div>'+evidenceDimensionCards(dimensions)+'</section>'+
  '<div class="report-two-column"><section class="card language-feedback" id="language-feedback"><div class="report-section-heading"><div><p class="eyebrow">COMMUNICATION</p><h2>表达反馈</h2></div>'+badge('不计入专业总分','gray')+'</div>'+evidenceDimensionCards(languages)+'<p class="page-note">仅评价转写能支持的清晰度、结构与术语使用，不评价发音、口音或真实语速。</p></section><section class="card official-feedback"><p class="eyebrow">INSTITUTION CRITERIA</p><h2>院校评分</h2>'+officialProvenance(s.profile)+'<div class="official-total">'+number(official.total)+'<small>'+(hasScore(official.total)?' / 100':'')+'</small></div><p class="subtle">'+esc(official.note??'未确认院校评分项时，不生成院校总分。')+'</p>'+(official.items?.length?official.items.map(d=>'<div class="official-result"><strong>'+esc(d.name)+'</strong><span>'+d.weight+'% / '+number(d.score)+'</span><p>'+esc(d.reason??'')+'</p>'+(d.quote?'<blockquote>'+esc(d.quote)+'</blockquote>':'')+'</div>').join(''):'<div class="empty official-empty"></div>')+'</section></div>'+
  '<section class="card next-practice" id="next-practice"><div class="report-section-heading"><div><p class="eyebrow">TWO THINGS TO PRACTICE</p><h2>下一轮练习重点</h2></div><span class="subtle">从证据缺口出发</span></div><div class="improvement-grid">'+(r.improvements??[]).slice(0,2).map((x,i)=>'<label class="improvement-card"><input type="checkbox" data-improvement="'+i+'" '+(x.checked?'checked':'')+'><span><small>重点 '+(i+1)+'</small><strong>'+esc(x.dimension??x.name??'下一步练习')+'</strong><p>'+esc(textValue(x.suggestion??x.improvement??x))+'</p></span></label>').join('')+(!(r.improvements??[]).length?'':'')+'</div><div class="probe-list">'+(r.nextProbes??[]).slice(0,2).map(x=>'<div><span>'+esc(x.dimension??x.name??'待补证据')+'</span><p>'+esc(textValue(x.question??x))+'</p></div>').join('')+'</div></section>'+
  '<section class="card evidence-ledger" id="evidence-ledger"><div class="report-section-heading"><div><p class="eyebrow">TRACEABLE EVIDENCE</p><h2>评价依据</h2></div><span class="subtle">原文 → 判断 → 边界 → 追问</span></div><div class="evidence-record-grid">'+quoted.map((e,i)=>evidenceCard(e,s,i)).join('')+(!quoted.length?'<div class="empty evidence-empty"><h3>暂无可引用的评价依据</h3><p></p></div>':'')+'</div>'+(pending.length?'<details class="pending-evidence"><summary>其他观察记录 / '+pending.length+' 条</summary><div class="pending-records">'+pending.map(e=>'<div><strong>'+esc(e.name??e.dimensionId)+'</strong>'+evidenceBadge(e)+'<p>'+esc(e.reason??e.limitation??'尚未取得足够回答证据')+'</p>'+(e.nextProbe?'<p class="subtle">下一追问：'+esc(textValue(e.nextProbe))+'</p>':'')+'</div>').join('')+'</div></details>':'')+'</section>'+
  '<div class="report-two-column"><section class="card"><h2>与上次可比练习对照</h2>'+(r.comparison?'<p class="subtle">第 '+r.comparison.attempt+' 次 / 目标与量表版本一致</p>'+(r.comparison.items??[]).map(x=>'<div class="comparison-row"><span>'+esc(x.name)+'</span><strong>'+(x.change==null?'证据不足':(x.change>0?'+':'')+x.change)+'</strong></div>').join(''):'<div class="empty">暂无同条件下的历史练习</div>')+'</section><section class="card"><h2>采集状态</h2><div class="sensor-grid">'+(r.sensorSummary??[]).map(x=>'<div class="sensor-cell"><strong>'+esc(sensorNames[x.channel]??x.channel)+'</strong><span class="subtle">'+(x.count?x.count+' 条状态事件':'未采集')+'</span></div>').join('')+'</div></section></div>'+reportQuestions(s)+
  '<details class="frozen-rubric"><summary>查看本场完整评分标准</summary>'+rubricPanel(s.profile,rubric)+'</details><div class="form-actions"><button class="secondary" data-action="new-attempt">再次练习</button></div>';
}
function sourceHTML(s,add=false){return `<article class="source"><div><h3><a href="${esc(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(s.summary).slice(0,260)}</p><span class="subtle">${esc([s.school,s.college,s.major].filter(Boolean).join(' / '))} / ${s.type==='official'?'官方来源（待核验）':s.type==='portfolio_reference'?'作品集参考':'经验信息'} / ${esc(s.retrievedAt?.slice(0,10)||'')}</span></div>${add?`<button class="small secondary" data-add-search="${searchResults.indexOf(s)}">保存</button>`:badge('待核验','gray')}</article>`;}
function sourceTargetFields(){return ['学校','学院','专业'].map((label,i)=>{const name=['school','college','major'][i];return `<label class="field">${label}<input name="${name}" value="${esc(draft[name]||'')}" readonly required></label>`;}).join('');}
function sourcePage(){return heading('参考资料','')+`
  <section class="card"><h2>当前检索目标</h2><form id="search-form">
    <div class="form-grid">${sourceTargetFields()}${formField('招生年份','year',draft.year,'number')}</div>
    <div class="source-search-actions"><p id="source-search-note" class="page-note">${!config.searchConfigured?'当前未连接检索服务，可在下方手动添加官方细则、专业能力资料、作品集参考或面试经验贴。':''}</p><div class="form-actions"><button class="source-primary" aria-describedby="source-search-note" ${config.searchConfigured?'':'disabled'}>联网补全与校验线索</button></div></div>
  </form>${searchResults.map(s=>sourceHTML(s,true)).join('')}</section>
  <section class="card"><h2>添加参考来源</h2><form id="source-form"><div class="form-grid">${sourceTargetFields()}<label class="field">来源类型<select name="type"><option value="official">院校官方资料</option><option value="experience">面试经验贴</option><option value="portfolio_reference">作品集参考</option></select></label>${formField('标题','title','')}${formField('网页链接','url','','url')}<label class="field">发布日期（选填）<input name="publishedAt" type="date"></label><label class="field wide">摘要与适用范围<textarea name="summary" placeholder="记录资料所对应的专业、年份、考核方式；经验贴只作练习线索，不视为官方标准。"></textarea></label></div><div class="form-actions"><button class="source-primary">保存来源</button></div></form></section>
  <section class="card"><h2>资料缓存</h2>${sources.length?sources.map(s=>sourceHTML(s)).join(''):'<div class="empty">还没有保存参考来源。</div>'}<p class="page-note">每条资料保留来源、获取时间与核验状态。作品集水平以实际作品和评分依据讨论，不从网上样例推算学生排名。</p></section>`;}
function render(){
  $('#app').innerHTML=({home,setup,'exam-library':()=>renderExamLibrary({library:examLibrary,templates:config.templates,target:draft,filter:libraryFilter}),devices,interview,reports,sources:sourcePage}[page]||home)();
  organizePage($('#app'),page);
  document.body.dataset.page=page;
  document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  document.querySelectorAll('[data-width]').forEach(el=>el.style.width=`${el.dataset.width}%`);
  for(const name of ['#local-preview','#interview-camera'])if($(name)&&camera)$(name).srcObject=camera;
  if($('.transcript'))$('.transcript').scrollTop=$('.transcript').scrollHeight;
  multimodal.sync(page,current).catch(e=>toast(e.message));
}
function navigate(){captureDraft();if($('#answer-form'))answerDraft=$('#answer-form textarea').value;stopSpeech();page=location.hash.slice(1)||'home';if(!labels[page])page='home';render();window.scrollTo({top:0,behavior:'instant'});}
async function refresh(){[materials,sessions,sources,examLibrary]=await Promise.all([api('/api/materials'),api('/api/sessions'),api('/api/sources'),api('/api/exam-library')]);}
async function run(fn){if(busy)return;busy=true;document.body.classList.add('busy');document.querySelectorAll('button:not([data-shell-control])').forEach(b=>b.disabled=true);try{await fn();}catch(e){toast(e.message);}finally{busy=false;document.body.classList.remove('busy');render();}}
async function upload(input){captureDraft();const kind=input.dataset.upload,file=input.files[0];if(!file)return;const form=new FormData();form.append('file',file);form.append('kind',kind);if(kind==='portfolio'&&draft.portfolioNotes)form.append('suppliedText',draft.portfolioNotes);toast('正在读取材料…');const m=await api('/api/materials',{method:'POST',body:form});materials.push(m);selected[kind]=m.id;if(kind==='rules')draft.rulesText=m.text;if(kind==='rubric')draft.rubricText=m.text;persist();toast(m.status==='needs_text'?'已保存原件，请在下方补充可读取的文字内容':'材料已保存');}
function stopSpeech(){if(recognition){recognition.stop();recognition=null;}recording=false;}
async function sense(channel,type,value){if(!current||current.status==='complete')return;try{current=await post(`/api/sessions/${current.id}/sensors`,{events:[{channel,type,value,atMs:Math.max(0,Date.now()-Date.parse(current.createdAt))}]});}catch{ /* Observation loss never blocks an answer. */ }}
async function toggleCamera(){await multimodal.camera();}
function speak(){if(!current)return;const q=[...current.turns].reverse().find(t=>t.role==='interviewer');const utterance=new SpeechSynthesisUtterance(q.content);utterance.lang=current.profile.stages[current.stageIndex].language;speechSynthesis.cancel();speechSynthesis.speak(utterance);}
function startSpeech(){
  if(recording){stopSpeech();return;}
  if(!speechConsent)throw new Error('请先勾选允许使用浏览器语音服务，或直接输入文字');
  const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition)throw new Error('此浏览器暂不支持语音转写，请使用文字输入');
  recognition=new SpeechRecognition();recognition.lang=current.profile.stages[current.stageIndex].language;recognition.continuous=true;recognition.interimResults=false;
  recognition.onresult=e=>{const box=$('#answer-form textarea');if(!box)return;for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)box.value+=`${box.value?' ':''}${e.results[i][0].transcript}`;answerDraft=box.value;};
  recognition.onerror=e=>{toast(`语音转写未完成（${e.error}），可继续文字输入`);stopSpeech();if(page==='interview')render();};
  recognition.onspeechstart=()=>sense('audio','speech_interval','browser_speech_start');
  recognition.onspeechend=()=>sense('audio','speech_interval','browser_speech_end');
  recognition.onend=()=>{recording=false;if($('#speech-status'))$('#speech-status').textContent='转写已结束，请检查文字后提交';};
  speechStarted=Date.now();recognition.start();recording=true;
}
document.addEventListener('change',e=>{
  if(e.target.dataset.libraryFilter){libraryFilter[e.target.dataset.libraryFilter]=e.target.value;if(e.target.dataset.libraryFilter==='schoolId')libraryFilter.collegeId='';render();return;}
  if(e.target.dataset.improvement!==undefined)run(async()=>{current=await post(`/api/sessions/${current.id}/improvements`,{index:Number(e.target.dataset.improvement),checked:e.target.checked});});
  if(e.target.matches('[data-upload]'))run(()=>upload(e.target));
  if(e.target.id==='speech-consent')speechConsent=e.target.checked;
  if(e.target.closest('#setup-form')&&['schoolId','collegeId','programId','directionId'].includes(e.target.name)) {
    const previous={...draft}; const field=e.target.name, value=e.target.value;
    captureDraft();
    const nextField=field==='schoolId'?'school':field;
    const nextValue=field==='schoolId'?(config.templates.find(t=>t.id===value)?.school==='自定义院校'?'':config.templates.find(t=>t.id===value)?.school||''):value;
    const changed=changeCatalogTarget(config.templates,{...draft,...Object.fromEntries(['school','collegeId','college','programId','major','directionId','direction','majorCode'].map(k=>[k,previous[k]??'']))},selected,nextField,nextValue);
    draft={...changed.target,schoolId:field==='schoolId'?value:draft.schoolId};selected=changed.materials;persist();render();return;
  }
  if(['school','college','major','year','admissionType'].includes(e.target.name)&&e.target.closest('#setup-form')) {
    const before=JSON.stringify([draft.school,draft.college,draft.major,draft.year,draft.admissionType]);captureDraft();
    if(before!==JSON.stringify([draft.school,draft.college,draft.major,draft.year,draft.admissionType])) {const changed=changeCatalogTarget(config.templates,draft,selected,e.target.name,draft[e.target.name]);draft=changed.target;selected=changed.materials;persist();render();}
  }
  if(e.target.closest('#setup-form'))captureDraft();
});
document.addEventListener('input',e=>{if(e.target.matches('#answer-form textarea')){answerDraft=e.target.value;if(!answerStarted)answerStarted=Date.now();}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;run(async()=>{
  if(form.id==='setup-form'){
    captureDraft();const materialIds=Object.values(selected).filter(id=>materials.some(m=>m.id===id));
    if(draft.portfolioNotes?.trim()){
      const description=new FormData();description.append('kind','portfolio');description.append('file',new Blob([draft.portfolioNotes],{type:'text/plain'}),'作品集项目说明.txt');const m=await api('/api/materials',{method:'POST',body:description});materials.push(m);materialIds.push(m.id);
    }
    const profile=await post('/api/profiles',{...draft,materialIds,stages:draft.stages.map(id=>({id,minutes:draft['minutes-'+id]})),officialRubric:draft.official.length?draft.official:null});
    toast('正在生成本场面试计划…');current=await post('/api/sessions',{profileId:profile.id});localStorage.setItem('onstage.active',current.id);answerDraft='';await refresh();location.hash='interview';page='interview';
  }else if(form.id==='answer-form'){
    const answer=form.elements.answer.value.trim();stopSpeech();toast('正在记录回答与生成反馈…');current=await post(`/api/sessions/${current.id}/answer`,{answer,questionId:current.turns.at(-1).id,inputMode:speechStarted?'speech':'text',durationMs:speechStarted?Date.now()-speechStarted:answerStarted?Date.now()-answerStarted:0});answerDraft='';speechStarted=0;answerStarted=0;
  }else if(form.id==='source-form'){await post('/api/sources',Object.fromEntries(new FormData(form)));await refresh();toast('来源已保存，核验状态为待核验');}
  else if(form.id==='search-form'){const r=await post('/api/search',Object.fromEntries(new FormData(form)));searchResults=r.results;toast(`找到 ${searchResults.length} 条待核验线索`);}
});});
document.addEventListener('click',e=>{
  const target=e.target.closest('button');if(!target||(target.form&&target.type==='submit'))return;
  if(target.hasAttribute('data-shell-control'))return;
  if(target.dataset.jumpAnswer){const record=document.getElementById('answer-'+target.dataset.jumpAnswer);if(record){window.scrollTo({top:window.scrollY+record.getBoundingClientRect().top-window.innerHeight/2+record.getBoundingClientRect().height/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});record.classList.add('answer-highlight');setTimeout(()=>record.classList.remove('answer-highlight'),2200);}return;}
  if(target.dataset.practice){draft.stages=[target.dataset.practice];persist();location.hash='setup';return;}
  if(target.dataset.action==='add-rubric'){captureDraft();draft.official.push({name:'',weight:'',criterion:''});persist();render();return;}
  if(target.dataset.loadExam){
    const record=examLibrary.records.find(x=>x.id===target.dataset.loadExam);
    if(!record||!examMatches(record,draft)){toast('请先选择相同学院、专业、年份、招生类型和适用方向');return;}
    draft={...draft,examLibraryId:record.id,rulesText:record.rulesText,rubricText:record.rubricText,official:structuredClone(record.officialRubric??[])};
    delete selected.rules;delete selected.rubric;persist();location.hash='setup';page='setup';render();toast('已载入匹配的官网规则');return;
  }
  if(target.dataset.removeRubric!==undefined){captureDraft();draft.official.splice(Number(target.dataset.removeRubric),1);persist();render();return;}
  if(target.closest('#multimodal-root'))return;
  run(async()=>{
    if(target.dataset.session){await multimodal.stop();stopSpeech();current=await api(`/api/sessions/${target.dataset.session}`);localStorage.setItem('onstage.active',current.id);answerDraft='';page=current.status==='complete'?'reports':'interview';location.hash=page;}
    if(target.dataset.control){if(['pause','finish'].includes(target.dataset.control))await multimodal.stop();stopSpeech();speechSynthesis.cancel();toast(target.dataset.control==='finish'?'正在生成复盘报告…':'正在处理…');current=await post(`/api/sessions/${current.id}/action`,{action:target.dataset.control});if(!['pause','resume'].includes(target.dataset.control)){answerDraft='';answerStarted=0;}await refresh();if(current.status==='complete'){location.hash='reports';page='reports';}}
    if(target.dataset.action==='camera')await toggleCamera();
    if(target.dataset.action==='mic-test'){if(mic){mic.getTracks().forEach(t=>t.stop());mic=null;}else mic=await navigator.mediaDevices.getUserMedia({audio:true,video:false});}
    if(target.dataset.action==='speech')startSpeech();
    if(target.dataset.action==='speak')speak();
    if(target.dataset.action==='new-attempt'){draft={...current.profile,stages:current.profile.stages.map(s=>s.id),official:current.profile.officialRubric||[],attempt:Number(current.profile.attempt)+1,interviewTime:new Date().toLocaleString('sv-SE').slice(0,16).replace(' ','T')};for(const s of current.profile.stages)draft['minutes-'+s.id]=s.minutes;selected={};for(const m of current.materials)selected[m.kind]=m.id;persist();location.hash='setup';page='setup';}
    if(target.dataset.addSearch!==undefined){await post('/api/sources',searchResults[Number(target.dataset.addSearch)]);await refresh();toast('检索线索已保存');}
  });
});
window.addEventListener('onstage-model-configured',event=>{if(config)config.mode=event.detail.mode;});
window.addEventListener('hashchange',navigate);
window.addEventListener('beforeunload',()=>{captureDraft();camera?.getTracks().forEach(t=>t.stop());mic?.getTracks().forEach(t=>t.stop());stopSpeech();});
setInterval(()=>{const timer=$('#elapsed');if(timer&&current){const sec=Math.floor((current.activeMs??0)/1000+(current.status==='active'?(Date.now()-Date.parse(current.lastResumedAt??current.createdAt))/1000:0));timer.textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}},1000);
try{config=await api('/api/config');const repaired=reconcileCatalogDraft(config.templates,draft,selected);draft=repaired.target;selected=repaired.materials;if(repaired.changed){persist();toast('目录已更新，请重新确认目标细则与评分标准');}await refresh();const active=localStorage.getItem('onstage.active');if(active){try{current=await api(`/api/sessions/${active}`);}catch{localStorage.removeItem('onstage.active');}}$('#runtime-mode').textContent=config.mode==='llm'?'模型已连接':'流程演示模式';navigate();}catch(e){$('#app').innerHTML=`<section class="card empty"><h2>暂时无法连接练习空间</h2><p>${esc(e.message)}</p></section>`;}
